/* Fonts (Atkinson Hyperlegible Next, Lexend, Roboto Mono) and Material Symbols Outlined
 * are loaded non-blocking via <link rel="stylesheet"> in index.html.
 * Consumer apps should include those <link> tags in their document <head>. */
@import "tailwindcss";

@custom-variant inverted (&:is([data-surface="inverted"] *, [data-prominence="inverted"] *));
@custom-variant focus-visible (&:focus-visible, &[data-preview~="focus"]);
@custom-variant active (&:active, &[data-preview~="active"]);
@custom-variant hover {
  @media (hover: hover) and (pointer: fine) {
    &:hover {
      @slot;
    }
  }
  &[data-preview~="hover"] {
    @slot;
  }
}
@custom-variant short (@media (max-height: 480px));

@theme {
  --font-heading: "Atkinson Hyperlegible Next", "Atkinson Fallback", sans-serif;
  --font-sans: "Lexend", "Lexend Fallback", sans-serif;
  --font-label: "Lexend", "Lexend Fallback", sans-serif;
  --font-mono: "Roboto Mono", "Mono Fallback", monospace;

  --color-background: var(--background);
  --color-on-background: var(--on-background);
  --color-surface: var(--surface);
  --color-on-surface: var(--on-surface);
  --color-on-surface-variant: var(--on-surface-variant);
  --color-surface-container-low: var(--surface-container-low);
  --color-surface-container-high: var(--surface-container-high);
  --color-outline: var(--outline);
  --color-outline-variant: var(--outline-variant);
  --color-state-hover: var(--state-hover);

  --color-primary: var(--primary);
  --color-on-primary: var(--on-primary);
  --color-primary-container: var(--primary-container);
  --color-on-primary-container: var(--on-primary-container);

  --color-secondary: var(--secondary);
  --color-on-secondary: var(--on-secondary);
  --color-secondary-container: var(--secondary-container);
  --color-on-secondary-container: var(--on-secondary-container);

  --color-tertiary: var(--tertiary);
  --color-on-tertiary: var(--on-tertiary);
  --color-tertiary-container: var(--tertiary-container);
  --color-on-tertiary-container: var(--on-tertiary-container);

  --color-error: var(--error);
  --color-on-error: var(--on-error);
  --color-error-container: var(--error-container);
  --color-on-error-container: var(--on-error-container);

  --color-warning: var(--warning);
  --color-on-warning: var(--on-warning);
  --color-warning-container: var(--warning-container);
  --color-on-warning-container: var(--on-warning-container);

  --color-success: var(--success);
  --color-on-success: var(--on-success);
  --color-success-container: var(--success-container);
  --color-on-success-container: var(--on-success-container);

  --color-neutral: var(--neutral);
  --color-on-neutral: var(--on-neutral);
  --color-neutral-container: var(--neutral-container);
  --color-on-neutral-container: var(--on-neutral-container);

  --border-width-default: 1px;
  --border-width-emphasis: 2px;
  --border-width-accent: 4px;

  --radius: 0.5rem;
  --radius-none: 0px;
  --radius-sm: 0.25rem;
  --radius-default: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;
}

/* `static` always emits these to :root so inline styles and raw CSS can use var(--shadow-*), var(--duration-*) etc. */
@theme static {
  /* Layered Ambient & Modal Shadows (Umbra + Penumbra) */
  --shadow-card: 0 1px 3px rgba(28, 26, 24, 0.06), 0 1px 2px rgba(28, 26, 24, 0.04);
  --shadow-toggle: 0 1px 2px rgba(28, 26, 24, 0.08);
  --shadow-ambient: 0 1px 3px rgba(28, 26, 24, 0.04), 0 4px 12px rgba(28, 26, 24, 0.06);
  --shadow-ambient-hover: 0 2px 4px rgba(28, 26, 24, 0.04), 0 8px 20px rgba(28, 26, 24, 0.08);
  --shadow-modal: 0 2px 6px rgba(28, 26, 24, 0.04), 0 8px 20px rgba(28, 26, 24, 0.06), 0 20px 48px rgba(28, 26, 24, 0.12);

  /* Motion Tokens */
  --duration-stagger: 40ms;
  --duration-micro: 80ms;
  --duration-quick: 150ms;
  --duration-fast: 250ms;
  --duration-medium: 350ms;
  --duration-slow: 400ms;
  --duration-very-slow: 500ms;
  --duration-emphasis: 500ms;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: ease-in-out;
  --ease-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --ease-spring: cubic-bezier(0.34, 1.45, 0.64, 1);

  --scale-large: 0.96;
  --scale-medium: 0.97;
  --scale-small: 0.98;
  --scale-tiny: 0.99;

  --distance-micro: 4px;
  --distance-small: 6px;
  --distance-base: 8px;
  --distance-medium: 12px;
  --distance-roomy: 16px;

  --blur-small: 2px;
  --blur-medium: 3px;
}

@theme {
  /* Spacing & Layout Tokens (DESIGN.md) */
  --spacing-gutter: var(--gutter);
  --spacing-gutter-mobile: var(--gutter-mobile);
  --spacing-margin-mobile: var(--margin-mobile);
  --spacing-margin-tablet: var(--margin-tablet);
  --spacing-margin-desktop: var(--margin-desktop);
  --container-measure: var(--measure);
  --container-page: var(--container-max);
  --spacing-container-max: var(--container-max);
}

:root {
  color-scheme: light;
  accent-color: var(--primary);
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  -webkit-tap-highlight-color: transparent;

  /* Safe Area Inset Tokens (Good CSS #47) */
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);

  --background: oklch(0.96 0.004 82);
  --on-background: oklch(0.22 0.005 80);
  --surface: oklch(1.00 0 0);
  --on-surface: oklch(0.22 0.005 80);
  --on-surface-variant: oklch(0.41 0.006 80);
  --surface-container-low: oklch(0.96 0.004 82);
  --surface-container-high: oklch(0.92 0.005 82);
  --outline: oklch(0.54 0.006 80);
  --outline-variant: oklch(0.83 0.006 82);
  --state-hover: color-mix(in oklch, var(--on-surface) 8%, transparent);
  --primary: #1B56E8;
  --on-primary: #ffffff;
  --primary-container: #E0E9FF;
  --on-primary-container: #001849;
  --secondary: #00796B;
  --on-secondary: #ffffff;
  --secondary-container: #D5F0EE;
  --on-secondary-container: #00201c;
  --tertiary: #F9A825;
  --on-tertiary: oklch(0.22 0.005 80);
  --tertiary-container: #fff0c2;
  --on-tertiary-container: #261900;
  --error: #C4161C;
  --on-error: #ffffff;
  --error-container: #ffdad6;
  --on-error-container: #450a0a;
  --warning: #A64B00;
  --on-warning: #ffffff;
  --warning-container: #FDE3B8;
  --on-warning-container: #331400;
  --success: #157331;
  --on-success: #ffffff;
  --success-container: #c8f5ce;
  --on-success-container: oklch(0.22 0.005 80);

  --neutral: oklch(0.30 0.005 80);
  --on-neutral: oklch(0.98 0.003 82);
  --neutral-container: oklch(0.87 0.006 82);
  --on-neutral-container: oklch(0.22 0.005 80);

  /* Spacing & Layout Tokens (DESIGN.md) */
  --spacing-base: 0.5rem;
  --gutter: 1.5rem;
  --gutter-mobile: 1rem;
  --margin-mobile: 1rem;
  --margin-tablet: 2rem;
  --margin-desktop: 4rem;
  --container-max: 80rem;
  --measure: 40rem;
  --header-height: 4.5rem;
}

/* Document-level overscroll containment, sticky anchor clearance & motion rules (Good CSS #45, #46) */
html {
  overscroll-behavior-y: none;
  scroll-padding-block-start: calc(var(--header-height, 4rem) + 1rem);
  scroll-padding-block-end: calc(var(--footer-height, 4rem) + 1rem);
}

@media (any-pointer: coarse) {
  html {
    overscroll-behavior-y: auto;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html:not([data-motion="reduce"]) {
    scroll-behavior: smooth;
  }
}

/* Global reduced-motion guard: collapses CSS transition durations & one-shot keyframes (preserving end-states/animationend) and disables infinite decorative sweeps */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    transition-delay: 0ms !important;
  }

  .animate-badge-pop,
  .animate-error-shake,
  .animate-text-reveal,
  .animate-step-forward,
  .animate-step-backward,
  .animate-roll-up,
  .animate-roll-down,
  .animate-check-pop,
  .animate-success-check,
  .animate-check-draw,
  .animate-digit-pop {
    animation-duration: 0.01ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
  }

  .animate-shimmer-sweep {
    animation: none !important;
  }
}

:root[data-motion="reduce"] *,
:root[data-motion="reduce"] *::before,
:root[data-motion="reduce"] *::after {
  transition-duration: 0.01ms !important;
  transition-delay: 0ms !important;
}

:root[data-motion="reduce"] .animate-badge-pop,
:root[data-motion="reduce"] .animate-error-shake,
:root[data-motion="reduce"] .animate-text-reveal,
:root[data-motion="reduce"] .animate-step-forward,
:root[data-motion="reduce"] .animate-step-backward,
:root[data-motion="reduce"] .animate-roll-up,
:root[data-motion="reduce"] .animate-roll-down,
:root[data-motion="reduce"] .animate-check-pop,
:root[data-motion="reduce"] .animate-success-check,
:root[data-motion="reduce"] .animate-check-draw,
:root[data-motion="reduce"] .animate-digit-pop {
  animation-duration: 0.01ms !important;
  animation-delay: 0ms !important;
  animation-iteration-count: 1 !important;
}

:root[data-motion="reduce"] .animate-shimmer-sweep {
  animation: none !important;
}

@layer base {
  /* Base UI root stacking prerequisites (portal isolation & iOS Safari backdrop/scroll-lock) */
  #root,
  #__next {
    isolation: isolate;
  }

  body {
    position: relative;
  }

  /* Tabular figures for tables, counters, metrics, and timestamps (Good CSS #21) */
  td,
  time,
  [data-tabular-nums] {
    font-variant-numeric: tabular-nums;
  }

  /* Defensive input zoom prevention on iOS Safari while respecting utility font sizes (Good CSS #01) */
  input,
  textarea,
  select {
    font-size: max(16px, 1rem);
  }

  /* Suppress native search clear button in WebKit/Blink to prevent double clear 'X' alongside custom clearable action */
  input[type="search"]::-webkit-search-cancel-button,
  input[type="search"]::-webkit-search-decoration,
  input[type="search"]::-webkit-search-results-button,
  input[type="search"]::-webkit-search-results-decoration {
    -webkit-appearance: none;
    appearance: none;
    display: none;
  }

  /* Prevent text selection highlight during rapid control activation (Good CSS #01) */
  button,
  [role="button"] {
    user-select: none;
    -webkit-user-select: none;
  }
}

/* Border Width Token Utility Classes */
@utility border-default {
  border-width: 1px;
}

@utility border-emphasis {
  border-width: 2px;
}

@utility border-accent {
  border-width: 4px;
}

/* Opt-in stable scrollbar gutter and scrollbar styling utilities */
@utility scrollbar-stable {
  scrollbar-gutter: stable;
}

@utility scrollbar-none {
  scrollbar-width: none;
  &::-webkit-scrollbar {
    display: none;
  }
}

@utility scrollbar-thin {
  scrollbar-width: thin;
  scrollbar-color: var(--outline-variant) transparent;
}

@layer base {
  /* Material Symbols icon styling helper */
  .material-symbols-outlined {
    --icon-fill: 0;
    --icon-grad: 0;
    --icon-opsz: 24;
    font-family: 'Material Symbols Outlined';
    font-size-adjust: none;
    font-weight: normal;
    font-style: normal;
    font-size: 24px;
    line-height: 1;
    letter-spacing: normal;
    text-transform: none;
    display: inline-block;
    width: 1em;
    height: 1em;
    overflow: hidden;
    white-space: nowrap;
    word-wrap: normal;
    direction: ltr;
    font-variation-settings: 'FILL' var(--icon-fill), 'wght' 400, 'GRAD' var(--icon-grad), 'opsz' var(--icon-opsz);
    transition: font-variation-settings var(--duration-quick, 150ms) var(--ease-standard, ease);
    -webkit-font-feature-settings: 'liga';
    font-feature-settings: 'liga';
    -webkit-font-smoothing: antialiased;
  }

  /* Optical grade compensation for inverted surfaces */
  [data-surface="inverted"] .material-symbols-outlined,
  [data-prominence="inverted"] .material-symbols-outlined {
    --icon-grad: -25;
  }

  @media (prefers-reduced-motion: reduce) {
    .material-symbols-outlined {
      transition: none;
    }
  }

  :root[data-motion="reduce"] .material-symbols-outlined {
    transition: none;
  }

  /* Mirror directional icons (arrows, chevrons, undo/redo, speaker waves) in RTL without flipping checkmarks/clocks/media playback */
  [dir="rtl"] .icon-directional,
  :dir(rtl) .icon-directional {
    scale: -1 1;
  }

  [dir="rtl"],
  :dir(rtl) {
    --badge-pop-x: 4px;
    --step-dir: -1;
  }
}

@layer base {
  /* Accessible high-visibility focus ring compatible with forced-colors mode (zero specificity via :where) */
  :where(*:focus-visible) {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
  }

  /* Suppress UA default black focus outline on mouse/pointer clicks while preserving WCAG keyboard focus */
  :focus:not(:focus-visible) {
    outline: none;
  }

  /* 1. Standard Form Controls (flush 2px focus ring fallback inside @layer base so utilities override cleanly) */
  :where(input:focus-visible, select:focus-visible, textarea:focus-visible),
  [data-slot="select-trigger"]:focus-visible,
  [data-slot="combobox-input-group"]:has(input:focus-visible),
  [data-slot="autocomplete-input-group"]:has(input:focus-visible),
  [data-slot="number-field-group"]:has(:focus-visible),
  [data-slot="input-group"]:has(input:focus-visible, textarea:focus-visible),
  [data-slot="prompt-input"]:has(textarea:focus-visible, input:focus-visible) {
    border-color: var(--primary);
    outline: 2px solid var(--primary);
    outline-offset: -1px;
  }

  /* 2. Composite Group inner controls: suppress redundant inner focus ring & border */
  [data-slot="input-group"] :where(input, textarea),
  [data-slot="prompt-input"] :where(input, textarea),
  [data-slot="combobox-input-group"] :where(input),
  [data-slot="autocomplete-input-group"] :where(input),
  [data-slot="number-field-group"] :where(input) {
    outline: none;
    box-shadow: none;
  }
  [data-slot="input-group"] :where(input, textarea):focus,
  [data-slot="input-group"] :where(input, textarea):focus-visible,
  [data-slot="prompt-input"] :where(input, textarea):focus,
  [data-slot="prompt-input"] :where(input, textarea):focus-visible,
  [data-slot="combobox-input-group"] :where(input):focus,
  [data-slot="combobox-input-group"] :where(input):focus-visible,
  [data-slot="autocomplete-input-group"] :where(input):focus,
  [data-slot="autocomplete-input-group"] :where(input):focus-visible,
  [data-slot="number-field-group"] :where(input):focus,
  [data-slot="number-field-group"] :where(input):focus-visible {
    outline: none;
    box-shadow: none;
  }
  [data-slot="number-field-group"] button:focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: -2px;
    box-shadow: none;
  }

  /* 3. Invalid / Error Form Controls (Overrides via cascade) */
  :where(
    input:is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible,
    select:is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible,
    textarea:is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible
  ),
  [data-slot="select-trigger"]:is([aria-invalid="true"], [data-invalid], .border-error):focus-visible,
  [data-slot="combobox-input-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):has(input:focus-visible),
  [data-slot="autocomplete-input-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):has(input:focus-visible),
  [data-slot="number-field-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):has(:focus-visible),
  [data-slot="input-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):has(input:focus-visible, textarea:focus-visible),
  [data-slot="prompt-input"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):has(textarea:focus-visible, input:focus-visible) {
    border-color: var(--error);
    outline: 2px solid var(--error);
    outline-offset: -1px;
  }

  /* 4. Discrete Buttons maintain floating 2px ring unless overridden by utilities or NumberField group */
  :where(button:focus-visible:not([data-slot="select-trigger"])) {
    outline: 2px solid var(--primary);
    outline-offset: 2px;
  }

  /* 5. Dropdown / Menu / Listbox Items: Inset outline for Windows High Contrast mode, prevents overflow clipping */
  [role="option"]:focus-visible,
  [role="menuitem"]:focus-visible,
  [role="menuitemcheckbox"]:focus-visible,
  [role="menuitemradio"]:focus-visible {
    outline: 2px solid transparent;
    outline-offset: -2px;
  }
}

/* Autofill Credential Highlighting: maintains calibrated surface tokens and typography on browser autofill */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
textarea:-webkit-autofill,
textarea:-webkit-autofill:hover,
textarea:-webkit-autofill:focus,
select:-webkit-autofill,
select:-webkit-autofill:hover,
select:-webkit-autofill:focus {
  -webkit-box-shadow: 0 0 0px 1000px var(--surface) inset !important;
  -webkit-text-fill-color: var(--on-surface) !important;
  caret-color: var(--primary);
  transition: background-color 5000s ease-in-out 0s;
}

input:autofill,
textarea:autofill,
select:autofill {
  box-shadow: 0 0 0px 1000px var(--surface) inset !important;
  filter: none;
}

/* Reduced motion preference: disable smooth page scroll while preserving calm opacity transitions and Floating UI positioner transforms */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto !important;
  }

  .transition-opacity {
    transition-property: opacity !important;
    transition-duration: var(--duration-quick, 150ms) !important;
  }
}

:root[data-motion="reduce"] {
  scroll-behavior: auto !important;
}

:root[data-motion="reduce"] .transition-opacity {
  transition-property: opacity !important;
  transition-duration: var(--duration-quick, 150ms) !important;
}

/* Canonical Motion & Transition Utilities */
@utility duration-stagger {
  transition-duration: var(--duration-stagger);
  animation-duration: var(--duration-stagger);
}

@utility duration-micro {
  transition-duration: var(--duration-micro);
  animation-duration: var(--duration-micro);
}

@utility duration-quick {
  transition-duration: var(--duration-quick);
  animation-duration: var(--duration-quick);
}

@utility duration-fast {
  transition-duration: var(--duration-fast);
  animation-duration: var(--duration-fast);
}

@utility duration-medium {
  transition-duration: var(--duration-medium);
  animation-duration: var(--duration-medium);
}

@utility duration-slow {
  transition-duration: var(--duration-slow);
  animation-duration: var(--duration-slow);
}

@utility duration-very-slow {
  transition-duration: var(--duration-very-slow);
  animation-duration: var(--duration-very-slow);
}

@utility duration-emphasis {
  transition-duration: var(--duration-emphasis);
  animation-duration: var(--duration-emphasis);
}

@utility stroke-dashoffset-0 {
  stroke-dashoffset: 0;
}

@utility animate-badge-pop {
  animation: badge-pop-in var(--duration-quick, 150ms) cubic-bezier(0.34, 1.36, 0.64, 1) both;
}

@utility animate-error-shake {
  animation: error-shake 300ms cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@utility animate-text-reveal {
  animation: text-reveal-rise var(--duration-very-slow, 500ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-forward {
  animation: step-slide-forward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-backward {
  animation: step-slide-backward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-roll-up {
  animation: roll-up 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-roll-down {
  animation: roll-down 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-check-pop {
  animation: t-check-circle-pop var(--duration-fast) var(--ease-smooth-out) forwards;
}

@utility animate-success-check {
  animation:
    t-check-fade var(--check-opacity-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards,
    t-check-transform var(--check-transform-dur, 500ms) cubic-bezier(0.34, 1.35, 0.64, 1) forwards,
    t-check-blur var(--check-blur-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@utility animate-check-draw {
  animation: t-check-draw var(--check-path-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) var(--check-path-delay, 80ms) both;
}

@utility animate-digit-pop {
  animation: digit-pop-in var(--digit-dur, 500ms) var(--ease-spring, cubic-bezier(0.34, 1.45, 0.64, 1)) both;
}

@utility animate-shimmer-sweep {
  animation: shimmer-sweep var(--shimmer-dur, 2000ms) linear infinite;
}

@keyframes badge-pop-in {
  0% {
    transform: translate(var(--badge-pop-x, -4px), 4px) scale(0);
    filter: blur(var(--blur-small, 2px));
    opacity: 0;
  }
  60% {
    transform: translate(0, 0) scale(1.15);
    filter: blur(0);
    opacity: 1;
  }
  100% {
    transform: translate(0, 0) scale(1);
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes error-shake {
  0% {
    transform: translateX(0);
  }
  16% {
    transform: translateX(calc(var(--shake-distance, 6px) * -1));
