/* Long-Form Content Rhythm (shadcn Typeset container system) */
@layer components {
  .typeset {
    --typeset-font-body: var(--font-sans);
    --typeset-font-heading: var(--font-heading);
    --typeset-font-mono: var(--font-mono);
    --typeset-size: 1em;
    --typeset-leading: 1.5;
    --typeset-flow: 1.25em;

    font-family: var(--typeset-font-body);
    font-size: var(--typeset-size);
    line-height: var(--typeset-leading);
    color: var(--on-surface);
    overflow-wrap: break-word;
  }

  /* Headings */
  .typeset :is(h1, h2, h3, h4, h5, h6):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-family: var(--typeset-font-heading);
    font-weight: 600;
    line-height: 1.25;
    margin-top: calc(var(--typeset-flow) * 1.2);
    margin-bottom: calc(var(--typeset-flow) * 0.5);
    color: var(--on-surface);
    overflow-wrap: break-word;
    text-wrap: balance;
  }

  .typeset h1:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 1.875em;
  }

  .typeset h2:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 1.5em;
  }

  .typeset h3:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 1.25em;
  }

  .typeset h4:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 1.125em;
  }

  .typeset h5:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 1em;
  }

  .typeset h6:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-size: 0.875em;
    color: var(--on-surface-variant);
  }

  /* Paragraphs & Text Flow */
  .typeset p:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    margin-top: 0;
    margin-bottom: var(--typeset-flow);
    color: var(--on-surface);
    overflow-wrap: break-word;
    text-wrap: pretty;
  }

  /* Lists with restored bullets, numbers, and indentation */
  .typeset ul:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    list-style-type: disc;
    padding-inline-start: 1.5em;
    margin-top: 0;
    margin-bottom: var(--typeset-flow);
    color: var(--on-surface);
    overflow-wrap: break-word;
  }

  .typeset ol:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    list-style-type: decimal;
    padding-inline-start: 1.5em;
    margin-top: 0;
    margin-bottom: var(--typeset-flow);
    color: var(--on-surface);
    overflow-wrap: break-word;
  }

  .typeset li:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    margin-top: calc(var(--typeset-flow) * 0.25);
    margin-bottom: calc(var(--typeset-flow) * 0.25);
    text-wrap: pretty;
  }

  .typeset li:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *))::marker {
    color: var(--on-surface-variant);
  }

  /* Nested lists */
  .typeset :is(ul, ol) :is(ul, ol):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    margin-top: calc(var(--typeset-flow) * 0.25);
    margin-bottom: 0;
