  .typeset pre:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-family: var(--typeset-font-mono);
    direction: ltr;
    unicode-bidi: isolate;
    font-size: 0.875em;
    background-color: var(--surface-container-low);
    color: var(--on-surface);
