  .typeset pre code:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    background-color: transparent;
    padding: 0;
    border: none;
    border-radius: 0;
    font-size: inherit;
    color: inherit;
  }

  /* Blockquotes */
  .typeset blockquote:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    margin-top: 0;
    margin-bottom: var(--typeset-flow);
    padding-inline-start: 1em;
    border-inline-start: 3px solid var(--primary);
