  }

  .typeset blockquote > p:last-child:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    margin-bottom: 0;
  }

  /* Links */
  .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    color: var(--primary);
    text-decoration: underline;
