  }

  .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)):hover {
    color: color-mix(in oklch, var(--primary) 85%, black);
  }

  /* Responsive horizontal scroll wrapper for markdown/HTML tables (keeps semantic <table> display intact) */
  .typeset-table-wrap {
    overflow-x: auto;
    max-width: 100%;
  }

  /* Tables */
  .typeset table:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0;
    margin-bottom: var(--typeset-flow);
    font-size: 0.875em;
  }

  .typeset :is(th, td):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    padding: 0.5em 0.75em;
    border-bottom: 1px solid var(--outline-variant);
    text-align: start;
  }

  .typeset th:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    font-weight: 600;
    color: var(--on-surface);
    overflow-wrap: break-word;
    background-color: color-mix(in oklch, var(--surface-container-high) 50%, transparent);
  }

  /* Horizontal Dividers */
  .typeset hr:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    border: 0;
    border-top: 1px solid var(--outline-variant);
    margin-top: calc(var(--typeset-flow) * 1.5);
    margin-bottom: calc(var(--typeset-flow) * 1.5);
  }

  /* Typeset opt-out isolation for embedded cards & interactive primitives */
  .typeset :where(.not-typeset, [data-not-typeset]) {
    margin-top: var(--typeset-flow);
    margin-bottom: var(--typeset-flow);
    font-size: 1rem;
    line-height: 1.5;
  }

  .typeset :where(.not-typeset, [data-not-typeset]) p:last-child {
    margin-bottom: 0;
  }

  /* Inverted surface overrides so .typeset prose inside <Card prominence="inverted"> stays high-contrast */
  [data-surface="inverted"] .typeset,
  [data-prominence="inverted"] .typeset {
    color: var(--on-neutral);
  }
  [data-surface="inverted"] .typeset :is(h1, h2, h3, h4, h5, p, ul, ol, th):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)),
  [data-prominence="inverted"] .typeset :is(h1, h2, h3, h4, h5, p, ul, ol, th):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    color: var(--on-neutral);
  }
  [data-surface="inverted"] .typeset :is(h6, blockquote):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)),
  [data-surface="inverted"] .typeset li:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *))::marker,
  [data-prominence="inverted"] .typeset :is(h6, blockquote):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)),
  [data-prominence="inverted"] .typeset li:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *))::marker {
    color: color-mix(in oklch, var(--on-neutral) 82%, transparent);
  }
  [data-surface="inverted"] .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)),
  [data-prominence="inverted"] .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
    color: var(--tertiary);
  }
  [data-surface="inverted"] .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)):hover,
  [data-prominence="inverted"] .typeset a:not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)):hover {
    color: color-mix(in oklch, var(--tertiary) 85%, white);
  }
  [data-surface="inverted"] .typeset :is(code, pre):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)),
  [data-prominence="inverted"] .typeset :is(code, pre):not(:where(.not-typeset, .not-typeset *, [data-not-typeset], [data-not-typeset] *)) {
