/* Scroll-Driven Reading Progress Indicator (MWG: scrollytelling / scroll-driven animations) */
@keyframes reading-progress-scale {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@media (prefers-reduced-motion: no-preference) {
  @supports ((animation-timeline: scroll()) and (animation-range: 0% 100%)) {
    :root:not([data-motion="reduce"]) .reading-progress-root-driven {
      transform-origin: left center;
      animation: reading-progress-scale auto linear;
      animation-timeline: scroll(root block);
      animation-range: 0% 100%;
      will-change: transform;
    }

    :root:not([data-motion="reduce"])[dir="rtl"] .reading-progress-root-driven,
    :root:not([data-motion="reduce"]) :dir(rtl) .reading-progress-root-driven {
      transform-origin: right center;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .reading-progress-root-driven {
    display: none;
  }
}

:root[data-motion="reduce"] .reading-progress-root-driven {
  display: none;
}

