  }

  @media (forced-colors: active) {
    .scrollspy-link[aria-current="true"] {
      border-inline-start: 3px solid Highlight;
      outline: 1px solid Highlight;
    }
  }
}

/* Swipe-to-reveal scroll container & initial target (MWG: swipe-to-reveal) */
.swipe-reveal-scroller {
  overscroll-behavior: auto;
}

.swipe-reveal-content {
  scroll-initial-target: nearest;
}

/* Container clipping boundary offset allowing floating focus rings and ambient drop-shadows to bleed unclipped (MWG: overflow-clipping-control) */
@supports (overflow-clip-margin: 8px) {
  .clip-safe-shadow {
    overflow: clip;
    overflow-clip-margin: 8px;
  }
}

/* Layout Containment Boundary: isolates reflow & recalculations in data-dense tables/grids (MWG: interactions-in-complex-layouts) */
.contain-layout {
  content-visibility: auto;
  contain-intrinsic-block-size: auto 300px;
}

@supports not (content-visibility: auto) {
  .contain-layout {
    contain: layout style paint;
  }
}

/* Legacy alias utility for inline-end-only rounded toast/alert framing */
@utility rounded-r-default {
  border-start-end-radius: var(--radius-default);
  border-end-end-radius: var(--radius-default);
}

/* Expand Touch Target Beyond Visual Size (Good CSS #27, WCAG 2.2 SC 2.5.8) */
@utility touch-target-expanded {
  position: relative;
  &::after {
    content: "";
    position: absolute;
    inset: min(0px, calc((100% - 44px) / 2));
    pointer-events: auto;
  }
}

/* Compositor-Only Shadow Lift via Opacity Crossfade (Good CSS #35) */
@utility card-lift {
  position: relative;
  isolation: isolate;

  &::before,
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }

  &::before {
    box-shadow: var(--shadow-ambient);
    opacity: 1;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  &::after {
    box-shadow: var(--shadow-ambient-hover);
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  @media (hover: hover) and (pointer: fine) {
    &:hover::before {
      opacity: 0;
    }
    &:hover::after {
      opacity: 1;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .card-lift::before,
  .card-lift::after {
    transition: none !important;
  }
}

:root[data-motion="reduce"] .card-lift::before,
:root[data-motion="reduce"] .card-lift::after {
  transition: none !important;
}

/* CSS Subgrid Card Layouts (Good CSS #09) */
@utility card-subgrid {
  display: grid;
  grid-row: span 3;
  grid-template-rows: subgrid;
  row-gap: 0.75rem;
}

@utility card-grid-subgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr));
}

/* Font-Relative Optical Icon Sizing (Good CSS #23) */
@utility icon-inline {
  display: inline-flex;
  align-items: baseline;
  gap: 0.5em;

  & > svg {
    flex: none;
    block-size: 1cap;
    inline-size: auto;
  }

  & > .material-symbols-outlined {
    flex: none;
    font-size: 1.15cap;
    line-height: 1;
    block-size: auto;
    inline-size: auto;
  }
}

@utility text-cap {
  font-size: 1.15cap;
  line-height: 1;
  vertical-align: baseline;
}

/* Safe Area Inset Utilities (Good CSS #47) */
@utility pt-safe {
  padding-top: max(var(--safe-top), 0px);
}

@utility pb-safe {
  padding-bottom: max(var(--safe-bottom), 0px);
}

@utility pl-safe {
  padding-left: max(var(--safe-left), 0px);
}

@utility pr-safe {
  padding-right: max(var(--safe-right), 0px);
}

@utility p-safe {
  padding-top: max(var(--safe-top), 0px);
  padding-bottom: max(var(--safe-bottom), 0px);
  padding-left: max(var(--safe-left), 0px);
  padding-right: max(var(--safe-right), 0px);
}

/* Safe Alignment Utilities for Scrollable Containers (Good CSS #13) */
@utility justify-safe-center {
  justify-content: safe center;
}

@utility items-safe-center {
  align-items: safe center;
}

/* Whole Card Clickable Link Pattern (Good CSS #28, Heydon Pickering Inclusive Cards) */
@utility card-link {
  position: static;
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
  }
  &:focus-visible {
    outline: 2px solid transparent;
  }
}

@utility card-interactive-child {
  position: relative;
  z-index: 1;
}

/* Opt-in keyword size interpolation (kept off :root so JS-measured Base UI panels do not interpolate auto <-> px) */
@utility interpolate-keywords {
  interpolate-size: allow-keywords;
}

/* ============================================================================
 * Modern Web Guidance 1.0 Enhancements
 * ============================================================================ */

/* 1. Visually Stable Font Fallbacks (MWG: visually-stable-font-fallbacks) */
@font-face {
  font-family: "Atkinson Fallback";
  src: local("Segoe UI"), local("Roboto"), local("Helvetica Neue"), local("Arial");
  size-adjust: 105%;
  ascent-override: 92%;
  descent-override: 24%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Lexend Fallback";
  src: local("Segoe UI"), local("Roboto"), local("Helvetica Neue"), local("Arial");
  size-adjust: 108%;
  ascent-override: 94%;
  descent-override: 24%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Mono Fallback";
  src: local("Cascadia Mono"), local("SFMono-Regular"), local("Consolas");
  size-adjust: 100%;
  ascent-override: 92%;
  descent-override: 24%;
}

/* Normalize fallback x-height strictly on typography classes (never *, body, or icon fonts) */
.font-sans,
.font-label,
.font-heading,
.font-mono,
.typeset {
  font-size-adjust: from-font;
}

/* 2. Physics-Based Spring Easing via linear() (MWG: physics-based-easing) */
@supports (animation-timing-function: linear(0, 1)) {
  :root {
    --ease-spring: linear(
      0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017,
      1.077, 1.121, 1.149 24.3%, 1.159, 1.163, 1.161, 1.154 29.9%, 1.129 32.8%,
      1.051 39.6%, 1.017 43.1%, 0.991, 0.977 51%, 0.974 53.8%, 0.975 57.1%,
      0.997 69.8%, 1.003 76.9%, 1.004 83.8%, 1
    );
  }
}

/* 3. Horizontal Soft Edge Content Fade (MWG: soft-edge-content-fade) */
@utility scroll-fade-x {
  scroll-padding-inline: 24px;
  -webkit-mask-image: linear-gradient(
    to right,
    transparent 0,
    black var(--fade-start, 0px),
    black calc(100% - var(--fade-end, 0px)),
    transparent 100%
  );
  mask-image: linear-gradient(
    to right,
    transparent 0,
    black var(--fade-start, 0px),
    black calc(100% - var(--fade-end, 0px)),
    transparent 100%
  );
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
}

[dir="rtl"] .scroll-fade-x,
:dir(rtl) .scroll-fade-x {
  -webkit-mask-image: linear-gradient(
    to left,
    transparent 0,
    black var(--fade-start, 0px),
    black calc(100% - var(--fade-end, 0px)),
    transparent 100%
  );
  mask-image: linear-gradient(
    to left,
    transparent 0,
    black var(--fade-start, 0px),
    black calc(100% - var(--fade-end, 0px)),
    transparent 100%
  );
}

/* 3b. Horizontal Edge Scroll Shadow for Data Tables (preserves 100% text contrast at scroll edges) */
@utility scroll-shadow-x {
  scroll-padding-inline: 24px;
  background-image:
    linear-gradient(
      to right,
      color-mix(in oklch, var(--on-surface) 10%, transparent),
      transparent
    ),
    linear-gradient(
      to left,
      color-mix(in oklch, var(--on-surface) 10%, transparent),
      transparent
    );
  background-position: left center, right center;
  background-size: var(--fade-start, 0px) 100%, var(--fade-end, 0px) 100%;
  background-repeat: no-repeat;
  background-attachment: scroll;
}

[dir="rtl"] .scroll-shadow-x,
:dir(rtl) .scroll-shadow-x {
  background-size: var(--fade-end, 0px) 100%, var(--fade-start, 0px) 100%;
}

@media (forced-colors: active) {
  .scroll-shadow-x {
    background-image: none;
    border: 1px solid CanvasText;
  }
}

/* 4. Higher-Order Density Token Reactivity (MWG: design-token-reactivity)
 * Supports both standalone `data-density` attributes and inherited `@container style(--density)` cascades. */
[data-density="compact"] {
  --density: compact;
  --density-table-cell-px: 0.75rem;
  --density-table-cell-py: 0.5rem;
  --density-table-row-min-h: 2.75rem;
  --density-card-padding: 1rem;
  --density-list-items-padding: 0.25rem;
  --density-detail-body-padding: 0.75rem;
}

[data-density="comfortable"] {
  --density: comfortable;
  --density-table-cell-px: 1rem;
  --density-table-cell-py: 0.875rem;
  --density-table-row-min-h: 3.5rem;
  --density-card-padding: 1.5rem;
  --density-list-items-padding: 0.5rem;
  --density-detail-body-padding: 1.5rem;
}

[data-density="spacious"] {
  --density: spacious;
  --density-table-cell-px: 1.5rem;
  --density-table-cell-py: 1rem;
  --density-table-row-min-h: 4rem;
  --density-card-padding: 2rem;
  --density-list-items-padding: 0.75rem;
  --density-detail-body-padding: 2rem;
}

@layer components {
  :where([data-slot="list-detail-block"] [data-slot="list-items"]) {
    padding: var(--density-list-items-padding, 0.5rem);
  }

  :where([data-slot="list-detail-block"] [data-slot="detail-body"]:not([data-flush="true"])) {
    padding: var(--density-detail-body-padding, 1.5rem);
  }

  @container style(--density: compact) {
    :where([data-slot="table-container"]:not([data-density])) {
      --density-table-cell-px: 0.75rem;
      --density-table-cell-py: 0.5rem;
      --density-table-row-min-h: 2.75rem;
    }
    :where([data-slot="card"]:not([data-density])) {
      --density-card-padding: 1rem;
    }
    :where([data-slot="list-detail-block"]:not([data-density])) {
      --density-list-items-padding: 0.25rem;
      --density-detail-body-padding: 0.75rem;
    }
  }

  @container style(--density: spacious) {
    :where([data-slot="table-container"]:not([data-density])) {
      --density-table-cell-px: 1.5rem;
      --density-table-cell-py: 1rem;
      --density-table-row-min-h: 4rem;
    }
    :where([data-slot="card"]:not([data-density])) {
      --density-card-padding: 2rem;
    }
    :where([data-slot="list-detail-block"]:not([data-density])) {
      --density-list-items-padding: 0.75rem;
      --density-detail-body-padding: 2rem;
    }
  }
}

/* 5. Dynamic Foreground Contrast for User-Supplied Colors (MWG: contrast-color) */
.contrast-auto {
  color: var(--chip-ink, var(--on-surface));
}

@supports (color: contrast-color(white)) {
  .contrast-auto {
    color: contrast-color(var(--dynamic-bg, var(--surface)));
  }
}

/* 6. Print Pagination Safety: unclip flex/dvh AppShell and ScrollArea containers and hide fixed navigation chrome */
@media print {
  [data-slot="sidebar-wrapper"],
  [data-slot="sidebar-inset"],
  [data-slot="app-shell-main"],
  [data-slot="scroll-area-viewport"] {
    display: block !important;
    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;
    overflow: visible !important;
  }

  [data-slot="sidebar"],
  [data-slot="sidebar-gap"],
  [data-slot="sidebar-rail"],
  [data-slot="navigation-bar"],
  [data-slot="scroll-area-scrollbar"] {
    display: none !important;
  }

  [data-slot="app-shell-header"] {
    position: static !important;
  }
}
